import argparse
import csv
import json

def clean_amount(s):
    s = s.strip()
    if not s:
        return None
    s = s.replace('$', '').replace(',', '')
    if s.startswith('(') and s.endswith(')'):
        s = '-' + s[1:-1]
    try:
        return float(s)
    except ValueError:
        return None

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('payload')
    args = parser.parse_args()
    params = json.loads(args.payload)
    path = params['path']
    total = 0.0
    with open(path, 'r', newline='') as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            print("0.00")
            return
        amount_idx = None
        for i, col in enumerate(header):
            if col.strip().lower() == 'amount':
                amount_idx = i
                break
        if amount_idx is None:
            print("0.00")
            return
        for row in reader:
            if not row or all(cell.strip() == '' for cell in row):
                continue
            if amount_idx < len(row):
                val = clean_amount(row[amount_idx])
                if val is not None:
                    total += val
    print(f"{total:.2f}")

if __name__ == '__main__':
    main()

import argparse
import json

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    cfg = json.loads(args.payload)
    path = cfg["path"]
    latest = {}
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            rec = json.loads(line)
            user = rec["user"]
            ts = rec["ts"]
            action = rec["action"]
            if user not in latest or ts > latest[user]["ts"]:
                latest[user] = {"ts": ts, "actions": [action]}
            elif ts == latest[user]["ts"]:
                latest[user]["actions"].append(action)
    count = 0
    for info in latest.values():
        if "logout" in info["actions"]:
            count += 1
    print(count)

if __name__ == "__main__":
    main()

import argparse, json, csv, sys

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("payload")
    args = parser.parse_args()
    config = json.loads(args.payload)
    path = config["path"]
    total = 0.0
    with open(path, newline='') as f:
        reader = csv.reader(f)
        header = next(reader, None)
        if header is None:
            print("0.00")
            return
        amount_idx = None
        for i, col in enumerate(header):
            if col.strip().lower() == 'amount':
                amount_idx = i
                break
        if amount_idx is None:
            print("0.00")
            return
        for row in reader:
            if not row or all(cell.strip() == '' for cell in row):
                continue
            if len(row) <= amount_idx:
                continue
            value = row[amount_idx].strip()
            if value == '':
                continue
            cleaned = ''.join(c for c in value if c not in '$,').strip()
            try:
                total += float(cleaned)
            except ValueError:
                pass
    print(f"{total:.2f}")

if __name__ == "__main__":
    main()
